import os.path
import time
from os import mkdir
from taf.rfrl.procedures.resources.python.external_devices.ue.exceptions import UERebootTimeout
from taf.rfrl.procedures.resources.python.external_devices.testpc.TestPC import TestPC
from taf.rfrl.procedures.resources.python.logger.logger import log_input_and_output


class Ue:
    """
    Responsible for remote Ue control
    """
    def __init__(self):
        self._tl_ue = None
        self._adb_ue_command = None
        self._alias = None
        self._ue_testpc = None
        self._default_wm_resolution = None
        self._default_wm_density = None

    def setup(self, tl_ue):
        """
        Setups environment for remote UE control.
        :param tl_ue: UE instance from TL init based on taf.config.testline.ue library
        :type tl_ue: Union[Qualcomm, Android, TafUeAndroid, MediaTek]
        """
        self._tl_ue = tl_ue
        self._adb_ue_command = f"adb -s {tl_ue.serial_number}"
        self._alias = f"UE_{tl_ue.serial_number}"
        self._ue_testpc = TestPC(hostname=tl_ue.ssh_connection_details.addr,
                                 username=tl_ue.ssh_connection_details.username,
                                 password=tl_ue.ssh_connection_details.password,
                                 alias=f"UE_{tl_ue.serial_number}")
        self._default_wm_resolution = self._get_default_wm_resolution()
        self._default_wm_density = self._get_default_wm_density()

    def reboot_ue_and_check_if_reachable(self, timeout=120):
        """
        Performs UE reboot with timeout.

        :param timeout: time in seconds for ue to become visible after reboot
        :type timeout: int
        :raises UERebootTimeout: when UE is not visible in devices list after provided timeout
        """
        self._ue_reboot()
        time.sleep(timeout)
        ues = self._get_ues_list()

        if self._tl_ue.serial_number not in ues:
            raise UERebootTimeout(f"UE with SN {self._tl_ue.serial_number} is not visible in available UEs list: {ues}")

    def change_wm_resolution(self, resolution):
        """
        Changes UE screen resolution. This procedure requires UE reboot for changes to be noticeable.
        :param resolution: UE screen resolution that will be applied, e.g. '1080x1920'
        :type resolution: str
        """
        self._change_wm_resolution(resolution=resolution)

    def change_to_default_wm_resolution(self):
        """
        Changes UE screen resolution to default value. This procedure requires UE reboot for changes to be noticeable.
        """
        self._change_wm_resolution(resolution=self._default_wm_resolution)

    def change_wm_density(self, pixel_density):
        """
        Changes UE screen pixel density. This procedure requires UE reboot for changes to be noticeable.
        :param pixel_density: UE screen pixel density that will be applied, e.g. '380'
        :type pixel_density: str
        """
        self._change_wm_density(density=pixel_density)

    def change_to_default_wm_density(self):
        """
        Changes UE screen pixel density to default value.
        This procedure requires UE reboot for changes to be noticeable.
        """
        self._change_wm_density(density=self._default_wm_density)

    def run_naa_app(self):
        """
        Runs NAA app on UE.
        """
        self._ue_testpc.execute_command(
            command=f"{self._adb_ue_command} shell "
                    f"am start -n com.nokia.android.application/com.nokia.android.application.NaaActivity"
        )

    def wake_ue_screen(self):
        """
        Simulates pressing POWER_UP button on UE.
        """
        self._ue_testpc.execute_command(
            command=f"{self._adb_ue_command} shell input keyevent 26")

    def unlock_ue_screen(self):
        """
        Simulates swipe up procedure on UE.
        """
        self._ue_testpc.execute_command(
            command=f"{self._adb_ue_command} shell input touchscreen swipe 500 800 500 0")

    def press_home_button(self):
        """
        Simulates pressing HOME button on UE.
        """
        self._ue_testpc.execute_command(
            command=f"{self._adb_ue_command} shell input keyevent KEYCODE_HOME")

    @log_input_and_output
    def get_ue_screenshot(self, file_name, logs_path):
        """
        Performs UE screenshot capture and downloads it to 'ue_screenshot' folder under provided logs path with
        filename that has UE prefix attached, e.g. 'UE_54abc_ETWS.png'
        :param file_name: name of a file (WITHOUT EXTENSION) that will be visible after UE prefix, e.g. 'ETWS'
        :type file_name: str
        :param logs_path: path under which new 'ue_screenshot' folder will be created with UE screenshots saved into,
                          e.g. /logs/path
        :type logs_path: str
        :returns: full path to captured UE screenshot, e.g. /logs/path/ue_screenshot/UE_54abc_ETWS.png
        :rtype: str
        """
        file_name_with_alias = f"{self._alias}_{file_name}.png"

        screenshot_path = self._prepare_screenshot_folder(logs_path=logs_path)
        self._perform_ue_screenshot(file_name=file_name_with_alias)

        self._download_ue_screenshot_to_testpc(file_name=file_name_with_alias)
        self._download_ue_screenshot_to_vm(file_name=file_name_with_alias, logs_path=screenshot_path)

        self._clear_ue_screenshot_from_remote(file_name=file_name_with_alias)

        return f"{screenshot_path}/{file_name_with_alias}"

    def get_ue_alias(self):
        """
        Returns UE alias generated for current session.
        :return: UE alias, e.g. 'UE_54abc'
        :rtype: str
        """
        return self._alias

    def _ue_reboot(self):
        self._ue_testpc.execute_command(command=f"{self._adb_ue_command} reboot")

    def _perform_ue_screenshot(self, file_name):
        self.wake_ue_screen()

        if not self._is_screen_turned_on():
            self.wake_ue_screen()
        if not self._is_screen_unlocked():
            self.unlock_ue_screen()

        self._ue_testpc.execute_command(command=f"{self._adb_ue_command} shell screencap -p /sdcard/{file_name}")

    def _download_ue_screenshot_to_testpc(self, file_name):
        self._ue_testpc.execute_command(command=f"{self._adb_ue_command} pull /sdcard/{file_name}")

    def _download_ue_screenshot_to_vm(self, file_name, logs_path):
        self._ue_testpc.download_file(remote_path=f"./{file_name}",
                                      local_path=f"{logs_path}/{file_name}")

    def _clear_ue_screenshot_from_remote(self, file_name):
        self._ue_testpc.execute_command(command=f"{self._adb_ue_command} shell rm /sdcard/{file_name}")
        self._ue_testpc.execute_command(command=f"rm {file_name}")

    @log_input_and_output
    def _get_default_wm_resolution(self):
        output = self._ue_testpc.execute_command_and_get_output(
            command=f"{self._adb_ue_command} shell wm size"
        )
        return output.split(":")[-1].strip()

    @log_input_and_output
    def _get_default_wm_density(self):
        output = self._ue_testpc.execute_command_and_get_output(
            command=f"{self._adb_ue_command} shell wm density"
        )
        return output.split(":")[-1].strip()

    @log_input_and_output
    def _get_ues_list(self):
        output = self._ue_testpc.execute_command_and_get_output(
            command="adb devices"
        )
        return output

    @log_input_and_output
    def _is_screen_turned_on(self):
        output = self._ue_testpc.execute_command_and_get_output(
            command=f"{self._adb_ue_command} shell dumpsys power | grep mWakefulness="
        )
        return "mWakefulness=Awake" in output

    @log_input_and_output
    def _is_screen_unlocked(self):
        output = self._ue_testpc.execute_command_and_get_output(
            command=f"{self._adb_ue_command} shell dumpsys window | grep mDreamingLockscreen="
        )
        return "mDreamingLockscreen=true" in output

    def _change_wm_resolution(self, resolution):
        self._ue_testpc.execute_command(
            command=f"{self._adb_ue_command} shell wm size {resolution}"
        )

    def _change_wm_density(self, density):
        self._ue_testpc.execute_command(
            command=f"{self._adb_ue_command} shell wm density {density}"
        )

    @staticmethod
    def _prepare_screenshot_folder(logs_path):
        screenshot_path = f"{logs_path}/ue_screenshots"

        if not os.path.exists(screenshot_path):
            mkdir(screenshot_path)
        return screenshot_path
